{
  "findings": [
    {
      "check_id": "AVD-AZU-0010",
      "title": "Trusted Microsoft Services bypass is not enabled",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "The network rules allow bypass only for Metrics and Logging, so trusted Microsoft services cannot bypass the storage firewall when required."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Allow\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\", \"AzureServices\"]\n}\n",
  "fix_summary": "Added AzureServices to the network-rule bypass list so trusted Microsoft services can access the storage account."
}
